    "sql": "-- AlterTable\nALTER TABLE `Card` ADD COLUMN `kind` ENUM('PHYSICAL', 'VIRTUAL') NOT NULL DEFAULT 'PHYSICAL';\n\n-- AlterTable\nALTER TABLE `AuditLog` MODIFY `action` ENUM(\n  'LOGIN',\n  'LOGIN_FAILED',\n  'LOGOUT',\n  'PATIENT_CREATE',\n  'PATIENT_UPDATE',\n  'RULE_CHANGE',\n  'CATEGORY_CHANGE',\n  'CARD_LINK',\n  'CARD_BLOCK',\n  'CARD_UNBLOCK',\n  'CARD_REPLACE',\n  'CARD_STOCK',\n  'CREDIT',\n  'REDEMPTION',\n  'ADJUSTMENT',\n  'REVERSAL',\n  'REPORT_EXPORT',\n  'PERMISSION_CHANGE',\n  'SETTINGS_CHANGE',\n  'OTP_REQUEST',\n  'MODULE_TOGGLE',\n  'TAG_ASSIGN',\n  'TAG_REMOVE',\n  'SEGMENT_CHANGE',\n  'TEMPLATE_CHANGE',\n  'COMMUNICATION_SEND',\n  'AUTOMATION_RUN',\n  'AUTOMATION_CHANGE',\n  'REFERRAL_CREATE',\n  'REFERRAL_CONVERT',\n  'NPS_RESPONSE',\n  'REWARD_REDEEM',\n  'VOUCHER_ISSUE',\n  'VOUCHER_REDEEM',\n  'GIFT_CARD',\n  'CONSENT_CHANGE',\n  'ACCELERATOR_CHANGE',\n  'API_KEY_CHANGE',\n  'WEBHOOK_DELIVERY',\n  'ONBOARDING_STEP',\n  'RAFFLE_CHANGE',\n  'RECEIPT_REVIEW',\n  'PREDICTION_RUN',\n  'PUSH_DEVICE',\n  'SCHEDULE_CHANGE',\n  'OTHER'\n) NOT NULL;\n\n-- CreateIndex\nCREATE INDEX `Card_clinicId_kind_status_idx` ON `Card`(`clinicId`, `kind`, `status`);\n"
